-- RLS performance: evaluate session settings ONCE, and index what the
-- policies filter on.
--
-- EXPLAIN before this change (Timetable, 12,637 rows):
--   Seq Scan ... Filter: school_id = current_setting(...) ...
--   Rows Removed by Filter: 11831 · Execution Time: 45.6 ms
-- current_setting() was re-evaluated for EVERY row, and with no index the
-- planner had to read every tenant's rows to return one school's — which is
-- exactly how one school's data volume slows down another school's queries.
--
-- Wrapping each call in (select ...) turns it into a once-evaluated InitPlan
-- (per Supabase's documented RLS guidance) and lets the planner use an index.
-- Only 46 of 181 school_id tables had a leading index; 7 had branch_id.
--
-- NOTE for production: CREATE INDEX takes a brief lock. Re-run these with
-- CREATE INDEX CONCURRENTLY (outside a transaction) on a live database.
-- Idempotent: safe to re-run.

CREATE INDEX IF NOT EXISTS "idx_AcademicPerformance_school_branch" ON "AcademicPerformance" (school_id, branch_id);
DROP POLICY IF EXISTS tenant_isolation ON "AcademicPerformance";
CREATE POLICY tenant_isolation ON "AcademicPerformance" USING ((school_id = (select current_setting('app.current_school_id', true)) AND (branch_id IS NULL OR (select current_setting('app.current_branch_ids', true)) = '' OR branch_id = ANY(string_to_array((select current_setting('app.current_branch_ids', true)), ',')))) OR (select coalesce(current_setting('app.bypass_rls', true), '')) = 'on') WITH CHECK ((school_id = (select current_setting('app.current_school_id', true)) AND (branch_id IS NULL OR (select current_setting('app.current_branch_ids', true)) = '' OR branch_id = ANY(string_to_array((select current_setting('app.current_branch_ids', true)), ',')))) OR (select coalesce(current_setting('app.bypass_rls', true), '')) = 'on');

