CREATE POLICY tenant_isolation ON "Vendor" USING ((school_id = (select current_setting('app.current_school_id', true)) AND (branch_id IS NULL OR (select current_setting('app.current_branch_ids', true)) = '' OR branch_id = ANY(string_to_array((select current_setting('app.current_branch_ids', true)), ',')))) OR (select coalesce(current_setting('app.bypass_rls', true), '')) = 'on') WITH CHECK ((school_id = (select current_setting('app.current_school_id', true)) AND (branch_id IS NULL OR (select current_setting('app.current_branch_ids', true)) = '' OR branch_id = ANY(string_to_array((select current_setting('app.current_branch_ids', true)), ',')))) OR (select coalesce(current_setting('app.bypass_rls', true), '')) = 'on');

